------------ LifeCycle ------------
function CatHouseExploreRewardCell:__init()
end

function CatHouseExploreRewardCell:__delete()
    self.controller = nil
end

function CatHouseExploreRewardCell:CleanField()
end

function CatHouseExploreRewardCell:Awake()
    self:InitCell()
end

function CatHouseExploreRewardCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
