------------ LifeCycle ------------

function CatHouseExploreRewardCell:InitCell()
    if isNull(self.cells) then self.cells = {} end
    local transBottomLeftPanel = self.Layout.transform
    for i = 1, transBottomLeftPanel.childCount do
        local childNodeName = string.format("GoodNode%d", i)
        local transChild = transBottomLeftPanel:Find(childNodeName)
        if not IsNull(transChild) then
            local luaBGoodsMB = KTool.GetComponent(transChild.gameObject, typeof(CS.Engine.Modules.LuaBehaviour))
            if luaBGoodsMB then
                luaBGoodsMB:Init()
                table.insert(self.cells, luaBGoodsMB.Env)
            end
        end
    end
end

function CatHouseExploreRewardCell:SetCellInfo(reward)
    if isNull(self.cells) or #self.cells <= 0 then return end
    for i = 1, #self.cells do
        local goodsNode = self.cells[i]
        local rewardData = reward[i]
        if not IsNull(rewardData) then
            local goodNodeData = {
                goodsId = rewardData.goodsId, -- goodId
                text = checkString(rewardData.goodsNum), -- 数量显示,
                isShowNo = true 
            }
            goodsNode:Reload(goodNodeData)
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodNodeData.goodsId)
            if isTable(vo) then
                goodsNode:SetClickButtonAction(function()
                    GameUtils.ShowCommonTipsBoard(goodsNode.controller.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                end)
            end
        end
        KTool.SetActive(goodsNode.controller.gameObject, not isNull(rewardData))
    end
end

return CatHouseExploreRewardCell
